int kirmizi=11;
int yesil=10;
void setup() {
  pinMode(kirmizi,OUTPUT);
  pinMode(yesil,OUTPUT);
}
void loop(){
  //Kırmızı LED
  digitalWrite(kirmizi,HIGH);
  digitalWrite(yesil,LOW);
  delay(1000);
  //Yeşil LED
  digitalWrite(kirmizi,LOW);
  digitalWrite(yesil,HIGH);
  delay(1000);
  //İki renk birlikte
  digitalWrite(kirmizi,HIGH);
  digitalWrite(yesil,HIGH);
  delay(1000);
  //İkisini de söndür
  digitalWrite(kirmizi,LOW);
  digitalWrite(yesil,LOW);
  delay(1000);

}
